import random
from collections import Counter
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
stops={'TAA','TAG','TGA'}
comp=str.maketrans('ACGT','TGCA')
def count_orfs(s,minlen=90):
    rc=s.translate(comp)[::-1]
    res=[]
    for strand,ss in (('+',s),('-',rc)):
        for f in range(3):
            i=f
            while i<len(ss)-2:
                if ss[i:i+3]=='ATG':
                    j=i
                    while j<len(ss)-2 and ss[j:j+3] not in stops: j+=3
                    if j-i+3>=minlen: res.append((j-i+3,strand,f))
                    i=j+3
                else: i+=3
    return res
